INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('b830d79b-d40a-40a7-b4d0-65fb2a77e9e0', NULL, NULL, NULL, '{"summary": "Premix possui vantagem competitiva em sustentabilidade e marca, mas precisa acelerar transformação digital e blindar-se contra volatilidade cambial para crescer com diferenciação.", "threats": [{"source": "fato", "content": "Volatilidade cambial (USD/BRL 5.78) pressionando custos de microingredientes importados", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Consolidação agressiva do setor via M&A por multinacionais capitalizadas", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Pressão ambiental internacional sobre carne brasileira afetando demanda do setor", "confidence": "Média"}, {"source": "estimativa", "content": "Disrupção digital por concorrentes com plataformas diretas ao produtor", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Pioneirismo em sustentabilidade com Fator P alinhado ao Plano ABC+ e demanda ESG global", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Marca Top of Mind no setor pecuário com 46 anos de tradição e credibilidade técnica", "confidence": "Alta"}, {"source": "fato", "content": "Rede de distribuição capilarizada e corpo técnico de campo robusto em todo Brasil", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Posição consolidada como desafiador Top Tier nacional em nutrição de ruminantes", "confidence": "Média"}], "weaknesses": [{"source": "análise de mercado", "content": "Gap digital frente a multinacionais que investem pesado em plataformas de venda direta", "confidence": "Alta"}, {"source": "fato", "content": "Alta dependência de insumos importados (fosfato, vitaminas) expostos à volatilidade cambial", "confidence": "Alta"}, {"source": "estimativa", "content": "Logística complexa e custosa para regiões remotas do Norte e Centro-Oeste", "confidence": "Média"}, {"source": "análise de mercado", "content": "Capacidade de investimento limitada vs multinacionais como Cargill e DSM-Firmenich", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Liderar mercado de carbono neutro com certificações de redução de metano entérico", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Desenvolver plataforma digital integrada com IA para consultoria e vendas B2B", "confidence": "Média"}, {"source": "fato", "content": "Capturar demanda ESG de exportadores pressionados pela EU Deforestation Regulation", "confidence": "Alta"}, {"source": "estimativa", "content": "Construir ecossistema de parcerias tecnológicas para ampliar lock-in com produtores", "confidence": "Média"}]}'::jsonb, '{"legal": ["Lei 14.515/2022 (Autocontrole) plenamente implementada exige conformidade rigorosa com BPF e registros MAPA", "Novas normas de rotulagem de rações em discussão podem exigir investimentos em embalagens e comunicação", "Certificações Global GAP e bem-estar animal tornam-se pré-requisito para atender grandes confinamentos exportadores"], "social": ["Demanda global por proteína animal sustentável (China/EUA) valoriza produtores com rastreabilidade e baixa emissão", "Pecuária de ciclo curto exige nutrição de alta performance, alinhada ao posicionamento técnico da Premix", "Pressão de consumidores por bem-estar animal e redução de antibióticos impulsiona aditivos naturais"], "summary": "Cenário favorece diferenciação sustentável: Fator P alinhado ao ABC+ e demanda ESG global. Riscos em câmbio/juros e gap digital frente a multinacionais. Priorizar certificações e plataforma digital para capturar valor.", "economic": ["SELIC 11.25% a.a. encarece capital de giro e investimentos de pecuaristas, podendo reduzir demanda por suplementação premium", "Dólar a R$ 5.78 pressiona custos de fosfato e vitaminas importadas, comprimindo margens da Premix", "Preços estáveis de milho/soja e recuperação do boi gordo (R$ 320/arroba) favorecem rentabilidade do cliente final"], "political": ["Reforma Tributária em discussão pode alterar carga fiscal sobre insumos agropecuários, impactando margens do setor de nutrição animal", "Plano Safra 2024/25 com foco em ABC+ abre oportunidade para produtos sustentáveis como Fator P (redução de metano)", "Tensão fiscal e cortes de gastos geram incerteza sobre subsídios e linhas de crédito rural para pecuaristas"], "environmental": ["EU Deforestation Regulation exige rastreabilidade total, criando barreira para exportadores sem certificação", "Regulamentação mais estrita sobre emissões de carbono na pecuária favorece pioneiros como Premix (Fator P)", "Pressão ambiental internacional sobre carne brasileira pode restringir mercados se não houver comprovação ESG"], "technological": ["Concorrentes investem pesado em plataformas digitais de venda direta, ameaçando modelo tradicional de revendas", "IoT em confinamentos e balanças inteligentes criam demanda por integração de dados nutricionais em tempo real", "Maturidade digital média (nota 6) da Premix é gap competitivo frente a multinacionais com e-commerce avançado"]}'::jsonb, '{"summary": "Setor de nutrição animal apresenta atratividade média com crescimento de 3-5% e barreiras altas protegendo incumbentes. Premix enfrenta rivalidade intensa de multinacionais capitalizadas, mas possui vantagens em marca, capilaridade e pioneirismo sustentável. Principais riscos: volatilidade cambial em insumos e disrupção digital por concorrentes. Oportunidades críticas: liderar em carbono neutro, integrar IA/dados e construir ecossistema de parcerias que amplie diferenciação técnica e lock-in com produtores.", "buyer_power": "Poder moderado. Pecuaristas pressionados por SELIC 11.25% buscam ROI comprovado. Demanda exportadora forte (China/EUA) sustenta otimismo, mas sensibilidade a preço aumenta em cenário de juros altos. Consultoria técnica reduz commoditização.", "supplier_power": "Poder moderado-alto. Volatilidade cambial (USD/BRL 5.78) encarece fosfato e vitaminas importadas da China. Milho/soja estáveis favorecem custos, mas dependência de microingredientes importados cria vulnerabilidade logística e de preço.", "disruption_ai_data": "Disrupção média-alta. Concorrentes investem em plataformas digitais de venda direta. IoT em confinamentos e balanças inteligentes geram dados valiosos. Premix deve integrar IA para nutrição de precisão e predição de desempenho animal.", "threat_substitutes": "Ameaça média-baixa no curto prazo. Carne cultivada é ameaça de longo prazo. Pressão ambiental internacional pode acelerar alternativas proteicas. Aditivos naturais vs antibióticos redefinem categoria, favorecendo inovadores como Premix (Fator P).", "competitive_rivalry": "Rivalidade alta com DSM-Firmenich, Cargill e Trouw investindo em plataformas digitais e linhas ''Carbono Neutro''. Consolidação via M&A (DSM+Firmenich) pressiona players nacionais. Premix deve acelerar diferenciação técnica e sustentável.", "threat_new_entrants": "Ameaça baixa. Barreiras altas: registro MAPA, BPF, escala logística e confiança técnica de marca (Premix desde 1978). Regulação de autocontrole e rastreabilidade UE elevam custos de compliance para novos entrantes.", "buyer_power_intensity": "Média", "overall_attractiveness": "Média", "strategic_implications": ["Acelerar plataforma digital própria com IA para nutrição de precisão, capturando dados de campo e criando barreira competitiva contra multinacionais", "Expandir linha ''Fator P'' com certificação de carbono neutro verificável, posicionando-se como líder em sustentabilidade antes da regulação obrigatória", "Desenvolver parcerias estratégicas com fintechs agrícolas e certificadoras internacionais para facilitar acesso a crédito verde e mercados de exportação premium", "Verticalizar fornecimento crítico de microingredientes via joint ventures ou contratos de longo prazo para mitigar volatilidade cambial e risco logístico China"], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Baixa", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Poder estratégico alto. Integração Lavoura-Pecuária (ILP) e Plano Safra ABC+ exigem ecossistemas colaborativos. Parcerias com certificadoras (Global GAP), fintechs agrícolas e plataformas IoT ampliam valor e lock-in com produtores.", "threat_new_entrants_intensity": "Baixa", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "90 dias focados em blindagem financeira via hedge cambial, mapeamento de certificações internacionais e seleção de fornecedor para plataforma digital B2B.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar governança de riscos e iniciar mapeamento para certificações internacionais", "investment": "R$ 80-120 mil", "key_results": ["Criar comitê de risco com reuniões mensais e política de hedge documentada até dia 30", "Contratar consultoria jurídica especializada em comércio exterior e regulação ambiental", "Mapear 100% dos gaps de conformidade das linhas Fator P e ABC+ para Global GAP"], "aligned_recommendation": "Proteção de Margens via Hedge Cambial e Diversificação de Fornecedores"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Implementar hedge cambial e iniciar qualificação de fornecedores alternativos", "investment": "R$ 100-150 mil", "key_results": ["Estruturar contratos de hedge para proteger 60% da exposição cambial em vitaminas e fosfatos", "Qualificar 3 fornecedores alternativos na América Latina e Índia com amostras aprovadas", "Definir escopo técnico e RFP para plataforma digital B2B com 5 fornecedores consultados"], "aligned_recommendation": "Proteção de Margens via Hedge Cambial e Diversificação de Fornecedores"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Consolidar blindagem financeira e iniciar projeto de plataforma digital", "investment": "R$ 120-180 mil", "key_results": ["Atingir 70% de cobertura de hedge cambial operacional com relatório mensal ao comitê", "Selecionar fornecedor de tecnologia para plataforma B2B e assinar contrato de desenvolvimento", "Concluir cronograma de adequação para certificação Global GAP com marcos trimestrais"], "aligned_recommendation": "Plataforma Digital de Relacionamento e Vendas B2B"}], "success_metrics": ["Política de hedge cambial operacional cobrindo 70% da exposição a insumos importados", "Roadmap de certificação Global GAP aprovado com gaps mapeados e cronograma definido", "Fornecedor de plataforma digital selecionado e contrato assinado para início do desenvolvimento"], "total_investment": "R$ 300-450 mil"}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Implementar hedge cambial, mapear certificações prioritárias e selecionar fornecedor de plataforma digital", "Médio Prazo (6-12 meses): Obter primeira certificação internacional, lançar MVP da plataforma B2B e pilotar programa de créditos de carbono", "Longo Prazo (12+ meses): Escalar plataforma de inteligência nutricional, monetizar marketplace de carbono e consolidar posição de líder ESG"], "key_findings": ["Modelo de plataforma de inteligência nutricional cria lock-in tecnológico impossível de replicar por concorrentes focados em volume", "Marketplace de créditos de carbono abre nova fonte de receita recorrente alinhada ao posicionamento sustentável", "Rede técnica de campo é ativo subutilizado que pode virar motor de aquisição viral entre pecuaristas"], "main_findings": ["FORÇA: Pioneirismo em aditivos sustentáveis (Fator P) e marca Top of Mind no setor pecuário com corpo técnico robusto", "FRAQUEZA: Gap digital significativo frente a multinacionais e dependência de commodities importadas sujeitas a câmbio", "OPORTUNIDADE: Demanda ESG global e Plano ABC+ criam janela para liderar em carbono neutro e certificações internacionais", "AMEAÇA: Multinacionais (DSM, Cargill) com capital infinito investindo em plataformas digitais e M&A agressivo no setor"], "important_notes": ["Hedge cambial é URGENTE: exposição a USD pode corroer margens em cenário de dólar a R$5.78 e tendência de alta", "Plataforma digital B2B não é diferencial futuro, é requisito de sobrevivência competitiva", "Certificações internacionais (EU Deforestation Regulation) são barreira de entrada para exportadores"], "central_challenge": "Transformar a Premix de fornecedora de suplementos em plataforma de inteligência nutricional, criando diferenciação sustentável frente a multinacionais capitalizadas enquanto protege margens da volatilidade cambial.", "executive_summary": "Premix possui vantagem competitiva sólida em sustentabilidade (Fator P) e marca reconhecida, mas enfrenta gap digital crítico frente a concorrentes e exposição cambial em insumos. A estratégia de oceano azul via plataforma de inteligência nutricional + marketplace de carbono é viável, porém exige execução disciplinada em 3 frentes: blindagem financeira imediata, certificações internacionais e transformação digital acelerada.", "strategic_priorities": ["Blindagem financeira: hedge cambial + diversificação de fornecedores de microingredientes", "Certificações internacionais: ISO 14001, Global GAP e compliance EU Deforestation", "MVP de plataforma digital B2B com IA para recomendação nutricional personalizada"], "overall_recommendation": "Executar transformação digital defensiva enquanto constrói diferenciação ofensiva via carbono. Prioridade zero: proteger margens do câmbio antes de investir em crescimento."}'::jsonb, '{"sam": "R$ 28B - R$ 35B", "som": "R$ 1.8B - R$ 2.8B", "tam": "R$ 95B - R$ 110B", "cagr": "+3.5% a +5.0% a.a. (baseado em: Sindirações 2025 + demanda exportadora)", "summary": "Mercado de R$100B com SAM de R$30B em ruminantes. Premix bem posicionada (Top 5) com SOM realista de R$1.8-2.5B. Diferenciação via sustentabilidade é crítica para crescer além do mercado.", "assumptions": ["TAM: Mercado brasileiro de nutrição animal 2024 ~R$100B (Sindirações: 85M ton × R$1.150/ton média)", "SAM: Segmento ruminantes = 30% do mercado total (~R$30B), foco Premix em suplementos premium", "SOM: Market share estimado 6-8% no segmento ruminantes (Top 5 nacional, atrás de DSM/Cargill)"], "confidence_level": 72, "calculation_notes": "Sindirações projeta 85-88M ton/ano. Premix compete no segmento premium de ruminantes (~30% do TAM). Receita estimada R$600-900M sugere 6-8% do SAM. Validado por porte (500-1000 func) vs concorrentes.", "data_sources_used": {"direct_data": ["Sindirações: Produção 85M ton/ano, faturamento setor R$95-105B", "Premix: 500-1000 funcionários, fundação 1978, receita estimada R$600-900M"], "proxy_calculations": ["Receita/funcionário setor: R$800k-1.2M/func → 700 func × R$1M = R$700M (valida estimativa)", "Market share: R$750M ÷ R$30B SAM = ~2.5% total, ~7% em ruminantes premium"], "benchmark_extrapolations": ["Top 5 players nacionais detêm ~35-40% do mercado de ruminantes", "Crescimento setor alinhado com PIB agro (+3-5% a.a.)"]}, "estimation_method": "proxy_concorrentes"}'::jsonb, '{"summary": "A Premix possui forte reconhecimento de marca e pioneirismo em sustentabilidade (Fator P), mas enfrenta gaps significativos em digitalização e certificação ambiental frente às multinacionais. DSM-Tortuga e Cargill-Nutron lideram em plataformas digitais e financiamento integrado, enquanto Trouw avança em IoT. Para crescer com diferenciação, a Premix deve acelerar sua transformação digital, buscar certificação carbono neutro e explorar parcerias tecnológicas para competir em P&D sem o capital das gigantes globais.", "best_practices": ["Tortuga lidera com programa de fidelização digital integrado a consultoria técnica remota via app proprietário", "Cargill Nutron oferece financiamento próprio atrelado ao Plano Safra, facilitando conversão de vendas", "Trouw Nutrition usa IoT em confinamentos parceiros para gerar dados e personalizar formulações em tempo real"], "performance_gaps": ["Plataforma digital de vendas diretas inferior às multinacionais (Cargill/DSM investem pesado em e-commerce B2B)", "Ausência de linha ''Carbono Neutro'' certificada, enquanto concorrentes já lançaram produtos com selo ambiental", "Menor capacidade de investimento em P&D biotecnológico comparado a players globais com M&A agressivo"], "competitors_analyzed": ["DSM-Firmenich (Tortuga)", "Cargill (Nutron)", "Trouw Nutrition (Bellman)", "Matsuda", "Connan"]}'::jsonb, '{"raise": ["Consultoria técnica preditiva com IA e dados de rebanho em tempo real", "Certificação e rastreabilidade carbono neutro como padrão em toda linha", "Integração digital com sistemas de gestão de fazendas e confinamentos"], "create": ["Plataforma ''Premix Intelligence'': ecossistema digital de nutrição conectada", "Modelo de assinatura com monitoramento contínuo e ajuste nutricional remoto", "Marketplace de créditos de carbono gerados pelos clientes certificados"], "reduce": ["Portfólio de SKUs de baixa rotação e margem reduzida", "Tempo de resposta técnica ao produtor (de dias para horas)", "Exposição cambial via nacionalização estratégica de microingredientes"], "summary": "A Premix deve transcender o modelo tradicional de venda de suplementos e posicionar-se como plataforma de inteligência nutricional. Ao criar um ecossistema digital que integra IA, dados de rebanho e certificação de carbono, a empresa transforma a relação transacional em parceria de longo prazo com lock-in tecnológico. O marketplace de créditos de carbono cria nova fonte de receita e diferenciação impossível de replicar por multinacionais focadas apenas em volume. Esta estratégia converte as fraquezas (escala menor que gigantes) em vantagem competitiva através de agilidade digital e propósito sustentável.", "eliminate": ["Dependência de vendedores generalistas sem expertise técnica profunda", "Catálogos impressos e materiais promocionais físicos de alto custo", "Processos manuais de formulação e recomendação nutricional"], "new_value_curve": "De fornecedor de insumos para orquestrador de ecossistema digital de nutrição sustentável com monetização de carbono."}'::jsonb, '{"summary": "Acelerar aquisição via rede técnica de campo + viralidade entre pecuaristas, monetizando com contratos recorrentes e expansão de portfólio sustentável (Fator P).", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Prospects chegam via consultores técnicos de campo, feiras agro (Expozebu, Feicorte), indicação de pecuaristas e conteúdo técnico no Instagram/YouTube.", "Engage: Envolver com diagnóstico nutricional gratuito na fazenda, webinars sobre redução de metano (Fator P) e cases de ROI em confinamentos.", "Activate: Converter com piloto de 60 dias com acompanhamento técnico dedicado, garantia de resultado mensurável (GPD, conversão alimentar).", "Propagate: Viralizar via programa ''Pecuarista Indica Pecuarista'' com bônus em produtos, depoimentos em vídeo e rankings de performance regional."], "metrics": ["CAC por canal (campo vs digital)", "Taxa de conversão piloto → cliente recorrente", "Coeficiente viral (indicações por cliente)", "Custo por lead qualificado em feiras"], "bottleneck": "Escalabilidade do time técnico de campo: crescimento limitado pela capacidade de consultores visitarem fazendas em regiões remotas do Norte/Centro-Oeste."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entregar valor com relatórios mensais de performance do rebanho, suporte técnico 24h via WhatsApp e ajustes de formulação em tempo real.", "Convert: Monetizar via contratos anuais de fornecimento com desconto progressivo, upsell de aditivos premium (Fator P) e serviços de consultoria avançada.", "Loop Back: Gerar recorrência com programa de reposição automática, alertas de estoque via app e renovação antecipada com condições especiais.", "Expand: Aumentar LTV expandindo para outras categorias (leite→corte), vendendo soluções de saúde animal e oferecendo certificação de sustentabilidade."], "metrics": ["LTV por segmento (corte vs leite vs confinamento)", "Taxa de renovação de contratos anuais", "Receita de expansão (cross-sell/upsell)", "NPS e taxa de churn por região"], "bottleneck": "Conversão de clientes de compra spot para contratos recorrentes: pecuaristas tradicionais resistem a compromissos de longo prazo por volatilidade de preços."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC permanece em 11-12%, dólar oscila entre R$5,50-6,00. Setor cresce 3-5% (Sindirações). Custos de fosfato e vitaminas importadas pressionam margens. Concorrentes DSM-Firmenich e Cargill intensificam digitalização e M&A. Premix mantém posição, mas precisa investir em plataforma digital para não perder relevância. Pressão ESG da UE exige rastreabilidade total até 2026.", "probability": 60, "required_actions": ["Implementar plataforma digital de vendas e relacionamento (B2B) em 12 meses", "Renegociar contratos de hedge cambial para microingredientes chineses", "Obter certificação de rastreabilidade para atender EU Deforestation Regulation", "Fortalecer corpo técnico de campo como diferencial vs. vendas digitais de concorrentes"]}, "summary": "Premix opera em cenário de oportunidade condicionada: o alinhamento com tendências ESG (Fator P, ABC+) e demanda exportadora forte são ventos favoráveis, mas vulnerabilidades em câmbio, juros e gap digital frente a multinacionais exigem ação imediata. Prioridade estratégica: (1) certificações internacionais para blindar diferenciação, (2) plataforma digital para não perder terreno competitivo, (3) hedge cambial e diversificação de fornecedores para proteger margens. Monitorar sinais de estresse macroeconômico e movimentos de M&A no setor como gatilhos para ativar planos de contingência.", "optimistic": {"name": "Cenário Otimista", "description": "SELIC recua para 9% em 2025, dólar estabiliza em R$5,20 e Reforma Tributária isenta insumos agro. Demanda chinesa acelera exportações de carne (+15%), arroba do boi atinge R$380. Plano ABC+ libera R$10bi em crédito verde. Premix capitaliza com Fator P certificado, conquistando 5pp de market share de multinacionais que não adaptaram portfólio ESG. Margem EBITDA sobe 4pp.", "probability": 20, "required_actions": ["Acelerar certificação internacional do Fator P (Global GAP, EU Deforestation Compliance)", "Expandir capacidade produtiva em 20% para atender demanda de exportadores", "Lançar linha premium ''Carbono Neutro Certificado'' com pricing diferenciado"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "SELIC sobe para 14%, dólar dispara a R$6,50 com crise fiscal. Reforma Tributária onera agro. UE bloqueia carne brasileira por desmatamento, arroba cai para R$250. Frete marítimo da China dobra, insumos sobem 40%. Multinacionais iniciam guerra de preços para consolidar mercado. Premix enfrenta queda de 15% em volume e pressão severa em margens. Risco de M&A hostil.", "probability": 20, "required_actions": ["Ativar plano de contingência com fornecedores alternativos (Índia, Europa)", "Reduzir SKUs de baixa margem e focar em produtos de alto valor agregado", "Buscar parceria estratégica ou investidor para fortalecer balanço contra M&A predatório"]}, "mitigation_tactics": ["Diversificar fornecedores de microingredientes (reduzir dependência China de 60% para 40%)", "Estruturar programa de hedge cambial de 6-12 meses para insumos dolarizados", "Acelerar diferenciação ESG com certificações antes que virem commodity", "Criar fundo de reserva equivalente a 3 meses de custos fixos para absorver choques"], "early_warning_signals": ["SELIC acima de 13% por 2 trimestres consecutivos (sinal de aperto monetário prolongado)", "Dólar sustentado acima de R$6,20 por 30 dias (pressão crítica em custos)", "Anúncio de M&A envolvendo concorrentes diretos (Matsuda, Connan) por multinacionais", "Bloqueio ou restrição de exportação de carne brasileira pela UE ou China", "Queda de 10%+ no preço da arroba do boi gordo em 60 dias"]}'::jsonb, '{"summary": "O BSC alinha a transformação da Premix de vendedora de suplementos para plataforma de inteligência nutricional, usando tecnologia e sustentabilidade como diferenciais competitivos contra multinacionais focadas em volume.", "customer": ["Alcançar 70% de retenção via lock-in tecnológico da plataforma de IA", "Converter 40% dos clientes transacionais em parceiros de longo prazo"], "financial": ["Gerar 15% da receita via marketplace de créditos de carbono até 2026", "Aumentar margem EBITDA em 5pp com serviços digitais de alto valor agregado"], "learning_growth": ["Capacitar 100% do time técnico em IA aplicada à nutrição animal", "Desenvolver competências internas em blockchain para rastreabilidade"], "internal_processes": ["Integrar dados de rebanho e certificação de carbono em plataforma única", "Lançar ecossistema digital de inteligência nutricional em 12 meses"]}'::jsonb, '{"score": "8.2/10", "summary": "A análise multicriterial indica que a estratégia de Certificações Internacionais oferece o melhor equilíbrio entre ROI sustentável, risco controlado e alinhamento com tendências de mercado (ESG, exportação). A Premix já possui ativos estratégicos (Fator P, corpo técnico) que facilitam esta rota. A Transformação Digital é complementar e necessária para não perder competitividade, mas apresenta maior complexidade de execução e dependência de compliance LGPD. O Hedge Cambial é ação tática imediata de proteção. Próximos passos: (1) Contratar consultoria jurídica para mapeamento regulatório de certificações; (2) Iniciar RFP para plataforma digital com requisitos LGPD; (3) Estruturar comitê de risco e política de hedge até Q1/2025. Revisão trimestral obrigatória com gatilhos de contingência ativados automaticamente.", "criteria": ["ROI e Sustentabilidade Financeira (Peso 40%)", "Risco Operacional e Jurídico (Peso 35%)", "Velocidade de Implementação e Time-to-Market (Peso 25%)"], "alternatives": ["Expansão via Certificações Internacionais e Diferenciação ESG", "Transformação Digital e Plataforma de Vendas Direta", "Diversificação Geográfica com Foco em Exportação"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Variação cambial USD/BRL superior a 15% em 60 dias", "Mudança regulatória que exija >10% de ajuste de custo operacional", "Nova exigência de licenciamento que bloqueie operação ou exportação", "Decisão judicial que afete modelo de negócio ou responsabilidade ambiental", "Falha de compliance LGPD/setorial com notificação da ANPD", "Movimento de M&A relevante no setor (aquisição de concorrente direto)", "Embargo comercial ou restrição de importação de insumos críticos", "Entrada de novo competidor com investimento superior a R$ 100M"]}, "score_comparison": "+18% acima da segunda opção (Transformação Digital: 6.9/10)", "monitoring_metrics": ["Taxa de conversão de certificações (% de linhas certificadas / total)", "Receita de exportação como % do faturamento total", "Custo de insumos importados vs. hedge realizado (efetividade do hedge)", "NPS de clientes digitais vs. canais tradicionais", "Market share em segmentos premium (Fator P, ABC+)", "Tempo médio de resposta técnica via plataforma digital", "Índice de concentração de fornecedores (HHI de supply chain)"], "recommended_option": "Expansão via Certificações Internacionais e Diferenciação ESG", "final_recommendation": "Priorizar certificações internacionais (Global GAP, ISO 14001) para blindar diferenciação ESG e habilitar exportação premium, enquanto implementa hedge cambial imediato para proteger margens contra volatilidade.", "priority_recommendations": [{"title": "Blindagem Competitiva via Certificações Internacionais", "budget": "R$ 350-500k", "priority": 1, "timeline": "12-18 meses", "description": "Obter certificações Global GAP, ISO 14001 e selo de conformidade com EU Deforestation Regulation para blindar diferenciação e habilitar exportação premium. Inclui adequação de processos produtivos, rastreabilidade de insumos e auditoria externa. Foco inicial nas linhas Fator P e ABC+ já alinhadas com tendências ESG."}, {"title": "Plataforma Digital de Relacionamento e Vendas B2B", "budget": "R$ 800k-1.2M", "priority": 2, "timeline": "9-12 meses", "description": "Desenvolver plataforma digital integrada com CRM, e-commerce B2B e ferramentas de suporte técnico remoto para pecuaristas. Objetivo: não perder terreno para multinacionais que investem pesado em canais digitais. Incluir calculadoras de nutrição, rastreabilidade de pedidos e integração com ERPs de clientes."}, {"title": "Proteção de Margens via Hedge Cambial e Diversificação de Fornecedores", "budget": "R$ 150-250k (estruturação) + custo de hedge variável", "priority": 3, "timeline": "3-6 meses", "description": "Estruturar política de hedge cambial para proteger 60-70% da exposição a insumos importados (vitaminas, fosfatos). Paralelamente, qualificar fornecedores alternativos na América Latina e Índia para reduzir dependência da China. Criar comitê de risco com reuniões mensais."}]}'::jsonb, 'approved', NULL, 166973, true, true, false, 'DT3BXDSQ', '2025-11-28 13:10:07.811911+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-28 13:02:14.00771+00'::timestamptz, '2025-11-28 13:15:25.984259+00'::timestamptz, '2025-11-28 13:05:00.615852+00'::timestamptz, NULL)
